import os

Import("env")

PROJECT_DIR = env.subst("$PROJECT_DIR")
WEB_DIR = os.path.join(PROJECT_DIR, "web")
OUT_PATH = os.path.join(PROJECT_DIR, "src", "web", "WebAssets.generated.h")

# (C++ symbol, file under web/)
ASSETS = [
    ("kIndexHtml", "index.html"),
    ("kAppCss", "app.css"),
    ("kAppJs", "app.js"),
]

DELIM = "E6RAW"


def build_header():
    chunks = [
        "#pragma once\n\n",
        "#include <Arduino.h>\n\n",
        "// AUTO-GENERATED by tools/embed_web_assets.py - do not edit by hand.\n",
        "// Edit the sources in web/ (index.html, app.css, app.js) instead.\n\n",
    ]
    for symbol, filename in ASSETS:
        path = os.path.join(WEB_DIR, filename)
        with open(path, "r", encoding="utf-8") as handle:
            content = handle.read()
        if ")" + DELIM + '"' in content:
            raise RuntimeError("raw-string delimiter clash in " + filename)
        chunks.append(
            'static const char {}[] PROGMEM = R"{}({}){}";\n\n'.format(
                symbol, DELIM, content, DELIM
            )
        )
    return "".join(chunks)


def generate():
    header = build_header()
    existing = None
    if os.path.isfile(OUT_PATH):
        with open(OUT_PATH, "r", encoding="utf-8") as handle:
            existing = handle.read()
    if existing == header:
        return
    with open(OUT_PATH, "w", encoding="utf-8", newline="\n") as handle:
        handle.write(header)
    print("embed_web_assets: regenerated " + os.path.relpath(OUT_PATH, PROJECT_DIR))


generate()
env.AddPreAction("buildprog", lambda *args, **kwargs: generate())
